# 全局速率限制阈值（基于 SQLite 实现）
GLOBAL_LOGIN_MAX = 20        # 每分钟允许的最大登录/注册 POST 请求
GLOBAL_LOGIN_WINDOW = 60     # 窗口秒数

def check_global_login_rate():
    #检查登录速率，超限返回 True
    db = get_db()
    now = time.time()
    cutoff = now - GLOBAL_LOGIN_WINDOW
    db.execute("DELETE FROM login_rate WHERE timestamp < ?", (cutoff,))
    count = db.execute("SELECT COUNT(*) FROM login_rate WHERE timestamp >= ?", (cutoff,)).fetchone()[0]
    db.commit()
    return count >= GLOBAL_LOGIN_MAX

def record_login_attempt():
    #记录一次登录尝试
    db = get_db()
    db.execute("INSERT INTO login_rate (timestamp) VALUES (?)", (time.time(),))
    db.commit()

def check_global_register_rate():
    #检查注册速率，超限返回 True
    db = get_db()
    now = time.time()
    cutoff = now - GLOBAL_LOGIN_WINDOW
    db.execute("DELETE FROM register_rate WHERE timestamp < ?", (cutoff,))
    count = db.execute("SELECT COUNT(*) FROM register_rate WHERE timestamp >= ?", (cutoff,)).fetchone()[0]
    db.commit()
    return count >= GLOBAL_LOGIN_MAX

