# HTML escape helper
def escape_html(text):
    return html_mod.escape(str(text), quote=True)

def is_safe_redirect(target):
    #只允许以 / 开头的相对路径，拒绝 // 或外部 URL"""
    return target.startswith('/') and not target.startswith('//')

# ---------------------------------------------------------------------------
# Database
# ---------------------------------------------------------------------------
def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DATABASE, check_same_thread=False, timeout=10)
        #数据库连接设置超时时间
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
        g.db.execute("PRAGMA journal_mode=WAL")   # 提升并发性能
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop("db", None)
    if db is not None:
        db.close()

def init_db():
    with app.app_context():
        db = get_db()
        db.executescript("""
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT UNIQUE NOT NULL,
                password_hash TEXT NOT NULL,
                role TEXT NOT NULL DEFAULT 'reader',
                failed_attempts INTEGER DEFAULT 0,
                locked_until TIMESTAMP,
                session_token TEXT
            );
            CREATE TABLE IF NOT EXISTS pages (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                slug TEXT UNIQUE NOT NULL,
                content_md TEXT NOT NULL DEFAULT '',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                updated_by INTEGER REFERENCES users(id) ON DELETE SET NULL
            );
            CREATE TABLE IF NOT EXISTS page_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                page_id INTEGER REFERENCES pages(id) ON DELETE CASCADE,
                content_md TEXT NOT NULL,
                edited_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
                edited_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
            CREATE TABLE IF NOT EXISTS login_rate (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp REAL NOT NULL
            );
            CREATE TABLE IF NOT EXISTS register_rate (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp REAL NOT NULL
            );
        """)
        db.commit()
    print(" Database initialized.")

# ---------------------------------------------------------------------------
# Auth helpers
# ---------------------------------------------------------------------------
def db_has_users():
    return get_db().execute("SELECT COUNT(*) FROM users").fetchone()[0] > 0

def get_current_user():
    uid = session.get("user_id")
    if not uid:
        return None
    return get_db().execute(
        "SELECT id, username, role, password_hash, session_token FROM users WHERE id = ?", (uid,)
    ).fetchone()

def require_login(role=None):
    if "user_id" not in session:
        if not db_has_users():
            return redirect(url_for("setup"))
        flash("Please log in first.", "warning")
        return redirect(url_for("login"))
    user = get_current_user()
    if not user:
        session.clear()
        flash("Account no longer exists.", "error")
        return redirect(url_for("login"))
    if role and user["role"] != role:
        abort(403)
    return None

def check_write_permission():
    check = require_login()
    if check:
        return check
    if get_current_user()["role"] not in ("admin", "writer"):
        abort(403)
    return None

