# 图片验证码生成（增强版：6位字符、随机旋转、彩色干扰）
def generate_captcha_image():
    """生成 6 位验证码图片，答案存于服务端内存，返回 PNG 字节流"""
    chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    code = ''.join(random.choices(chars, k=6))
    key = uuid.uuid4().hex
    now = time.time()

    # 存入内存，并清理过期验证码（有效期 5 分钟）
    with captcha_lock:
        expired = [k for k, v in captcha_store.items() if now - v['timestamp'] > 300]
        for k in expired:
            del captcha_store[k]
        captcha_store[key] = {'code': code.upper(), 'timestamp': now}

    session['captcha_key'] = key   # 仅把随机 key 传给客户端

    # 加大画布以适应6位字符
    img = Image.new('RGB', (160, 50), color=(255, 255, 255))
    draw = ImageDraw.Draw(img)

    # 从内嵌 base64 解码字体
    try:
        font_data = io.BytesIO(base64.b64decode(FONT_BASE64))
        font = ImageFont.truetype(font_data, 28)  # 稍微缩小字号以便6个字符
    except Exception:
        font = ImageFont.load_default()

    # 为每个字符单独旋转后粘贴
    for i, ch in enumerate(code):
        # 创建临时透明画布
        char_img = Image.new('RGBA', (30, 40), (255, 255, 255, 0))
        char_draw = ImageDraw.Draw(char_img)
        char_draw.text((0, 0), ch, fill=(0, 0, 0), font=font)
        rotated = char_img.rotate(random.randint(-30, 30), expand=1, fillcolor=(255, 255, 255, 0))
        x = 8 + i * 26 + random.randint(-2, 2)
        y = random.randint(2, 8)
        img.paste(rotated, (x, y), rotated)

    # 彩色干扰线
    for _ in range(5):
        x1 = random.randint(0, 60)
        y1 = random.randint(0, 45)
        x2 = random.randint(100, 160)
        y2 = random.randint(0, 45)
        color = (random.randint(100, 200), random.randint(100, 200), random.randint(100, 200))
        draw.line([(x1, y1), (x2, y2)], fill=color)

    # 高密度噪点
    for _ in range(400):
        x = random.randint(0, 159)
        y = random.randint(0, 49)
        draw.point((x, y), fill=(random.randint(0, 255), random.randint(0, 255), random.randint(0, 255)))

    # 整体轻微旋转
    img = img.rotate(random.uniform(-10, 10), fillcolor=(255, 255, 255))

    buf = io.BytesIO()
    img.save(buf, format='PNG')
    buf.seek(0)
    return buf


def verify_captcha(user_input):
    """验证用户输入的验证码（不区分大小写，一次性消费）"""
    key = session.pop('captcha_key', None)
    if not key:
        return False
    with captcha_lock:
        entry = captcha_store.pop(key, None)
    if not entry:
        return False
    return entry['code'] == user_input.strip().upper()


def generate_session_token():
    return secrets.token_hex(32)

# ---------------------------------------------------------------------------
# Markdown
# ---------------------------------------------------------------------------
class WikiRenderer(mistune.HTMLRenderer):
    #Convert [text](#slug) to /slug, and [text](##anchor) to #anchor"""

    def heading(self, text, level):
        #为标题生成 id，例如 '## My Section' -> <h2 id="my-section">My Section</h2>
        # 生成 id：小写，去掉首尾空格，替换空格为连字符，仅保留字母数字和连字符
        slug_id = re.sub(r'[^\w\s-]', '', text.lower()).strip().replace(' ', '-')
        return f'<h{level} id="{slug_id}">{text}</h{level}>'
    
    def link(self, text, url, title=None):
        if url.startswith("##"):
            # 页内锚点：例如 [go](##section) → <a href="#section">go</a>
            anchor = url[2:]
            # 去掉一个 #，保留剩余部分作为锚点；仅允许合法字符，防止不规范输入
            if not re.fullmatch(r"[a-zA-Z0-9_\-\.]+", anchor):
                anchor = ''
            # 不合法则忽略，生成 # 链接（回到顶部）
            url = f'#{anchor}'
        elif url.startswith("#") and not url.startswith("#!"):
            # 内部 Wiki 链接：[page](#slug) → /slug
            slug = url[1:]
            if re.fullmatch(r"[a-zA-Z0-9_\-]+", slug):
                url = f"/{slug}"
        return super().link(text, url, title)


def md2html(md_text: str) -> str:
    markdown = mistune.create_markdown(renderer=WikiRenderer(escape=True))
    return markdown(md_text)

# ---------------------------------------------------------------------------
# History limit
# ---------------------------------------------------------------------------
HISTORY_MAX = 100

def add_history(page_id, content_md, user_id, timestamp):
    db = get_db()
    db.execute(
        "INSERT INTO page_history (page_id, content_md, edited_by, edited_at) VALUES (?,?,?,?)",
        (page_id, content_md, user_id, timestamp),
    )
    count = db.execute(
        "SELECT COUNT(*) FROM page_history WHERE page_id = ?", (page_id,)
    ).fetchone()[0]
    if count > HISTORY_MAX:
        db.execute(
            "DELETE FROM page_history WHERE page_id = ? AND id NOT IN "
            "(SELECT id FROM page_history WHERE page_id = ? ORDER BY edited_at DESC LIMIT ?)",
            (page_id, page_id, HISTORY_MAX),
        )
    db.commit()

