@app.route("/login", methods=["GET", "POST"])
def login():
    if not db_has_users():
        flash("⚠️ No admin account exists. Please set up first.", "warning")
        return redirect(url_for("setup"))

    if request.method == "POST":
    # 全局速率检查
        if check_global_login_rate():
           flash("Too many login attempts. Please wait a moment.", "error")
           return render_template_string(BASE, title="Login", content=login_form()), 429

        honeypot_check()

    # ---------- 验证码检查 ----------
        if not verify_captcha(request.form.get("captcha", "")):
            flash("Incorrect answer to the security question.", "error")
            return render_template_string(BASE, title="Login", content=login_form())

    # 验证码正确，现在记录有效尝试
        record_login_attempt()


        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")
        db = get_db()
        user = db.execute("SELECT * FROM users WHERE username = ?", (username,)).fetchone()

        # 统一错误提示
        if user:
            # 检查锁定（使用 datetime 对象比较）
            locked = False
            if user["locked_until"]:
                try:
                    locked_time = datetime.strptime(user["locked_until"], TIME_FORMAT).replace(tzinfo=timezone.utc)
                    if locked_time > datetime.now(timezone.utc):
                        locked = True
                except ValueError:
                    pass
            if locked:
                flash("Invalid username or password.", "error")
                return render_template_string(BASE, title="Login", content=login_form())

            if check_password_hash(user["password_hash"], password):
                # 登录成功
                db.execute("UPDATE users SET failed_attempts=0, locked_until=NULL WHERE id=?", (user["id"],))
                db.commit()
                session.clear()
                # 生成新会话令牌，写入数据库和 session
                new_token = generate_session_token()
                db.execute("UPDATE users SET session_token = ? WHERE id = ?", (new_token, user["id"]))
                db.commit()
                session["session_token"] = new_token
                session["_csrf_token"] = os.urandom(32).hex()
                session["user_id"] = user["id"]
                session["username"] = user["username"]
                session["role"] = user["role"]
                flash("Logged in.", "success")
                next_url = request.args.get("next")
                if next_url and is_safe_redirect(next_url):
                    return redirect(next_url)
                return redirect(url_for("index"))
            else:
                # 登录失败：递增计数器并可能锁定
                attempts = (user["failed_attempts"] or 0) + 1
                locked_until = None
                if attempts >= LOCKOUT_THRESHOLD:
                    locked_until = (datetime.now(timezone.utc) + timedelta(minutes=LOCKOUT_DURATION)).strftime(TIME_FORMAT)
                db.execute("UPDATE users SET failed_attempts=?, locked_until=? WHERE id=?",
                           (attempts, locked_until, user["id"]))
                db.commit()
        else:
            pass

        flash("Invalid username or password.", "error")

    return render_template_string(BASE, title="Login", content=login_form())


