@app.route("/change_password", methods=["GET", "POST"])
def change_password():
    check = require_login()
    if check:
        return check

    user = get_current_user()
    if not user or user["session_token"] != session.get("session_token"):
        session.clear()
        flash("Session expired. Please log in again.", "warning")
        return redirect(url_for("login"))

    if request.method == "POST":
        # honeypot_check()   #这个位置其实无需蜜罐。
        old_pw = request.form.get("old_password", "")
        new_pw = request.form.get("new_password", "")
        if not old_pw or not new_pw:
            flash("Both fields are required.", "error")
        elif len(new_pw) < 8:
            flash("New password must be at least 8 characters.", "error")
        elif not check_password_hash(user["password_hash"], old_pw):
            flash("Old password is incorrect.", "error")
        else:
            try:
                db = get_db()
                db.execute("UPDATE users SET password_hash = ? WHERE id = ?",
                           (generate_password_hash(new_pw), user["id"]))
                # 生成新令牌，强制其他所有会话失效
                new_token = generate_session_token()
                db.execute("UPDATE users SET session_token = ? WHERE id = ?", (new_token, user["id"]))
                db.commit()
                # 更新当前会话的令牌，这样当前用户不会被踢出
                session["session_token"] = new_token
                flash("Password changed. All other sessions have been invalidated.", "success")
                return redirect(url_for("index"))
            except Exception as e:
                # 打印错误到终端，便于调试
                print(f"Change password error: {e}", file=sys.stderr)
                flash("An error occurred while updating the password. Please try again.", "error")

    token = generate_csrf_token()
    c = f"""<h1>Change Password</h1>
<form method="post">
  <input type="hidden" name="_csrf_token" value="{token}">
  <input class="honeypot" type="text" name="email_confirm" autocomplete="off" tabindex="-1">
  <label>Old password: <input type="password" name="old_password" required></label>
  <label>New password: <input type="password" name="new_password" required minlength="8"></label>
  <input type="submit" value="Change">
</form>"""
    return render_template_string(BASE, title="Change Password", content=c)

